    n = 26
    # We want a 3-regular graph with girth >= 7
    # Let's use z3

    # Variables: A[i][j] is a boolean indicating if edge (i, j) exists
    A = [[Bool(f"A_{i}_{j}") for j in range(n)] for i in range(n)]

