    # Degree 3
    for i in range(n):
        s.add(PbEq([(A[i][j], 1) for j in range(n)], 3))

    # Girth >= 7 means no cycles of length 3, 4, 5, 6
    # Instead of all cycles, we can say: for any pair of vertices (i, j),
    # there is at most one path of length <= 3 between them.
    # Actually, it's easier to define distance variables.
    # But distance variables are expensive.

    # Let's just add clauses for cycles of length 3, 4, 5, 6.
    # To reduce the number of clauses, we can just use a lazy approach:
    # Solve, find a short cycle, add a clause to forbid it, repeat.

    import networkx as nx

    while True:
        if s.check() == sat:
            m = s.model()
            adj = {i: [] for i in range(n)}
            for i in range(n):
