                    for w in adj[v]:
                        if w not in dist:
                            dist[w] = dist[v] + 1
                            parent[w] = v
                            queue.append(w)
                        elif parent[v] != w:
                            cycle_len = dist[v] + dist[w] + 1
                            if cycle_len < girth:
                                girth = cycle_len
                                # Reconstruct cycle
                                path1 = []
                                curr = v
                                while curr is not None:
                                    path1.append(curr)
                                    curr = parent[curr]
                                path1.reverse()

                                path2 = []
                                curr = w
                                while curr is not None:
                                    path2.append(curr)
                                    curr = parent[curr]

                                # Find lowest common ancestor
                                lca = None
                                for p1, p2 in zip(path1, path2):
                                    if p1 == p2:
                                        lca = p1
                                    else:
                                        break

                                idx1 = path1.index(lca)
                                idx2 = path2.index(lca)

                                cycle = path1[idx1:] + path2[idx2:][::-1]
                                short_cycle = cycle

            if girth >= 7:
