                for i in range(n):
                    for j in range(i + 1, n):
                        if is_true(m[A[i][j]]):
                            edges.append((i, j))
                print(edges)
                return
            else:
                # Forbid this cycle
                clause = []
                for i in range(len(short_cycle)):
                    u = short_cycle[i]
                    v = short_cycle[(i + 1) % len(short_cycle)]
                    clause.append(Not(A[u][v]))
                s.add(Or(clause))
        else:
            print("UNSAT")
            return

